INSERT INTO Language_en_US(Tag,Text) VALUES
('TXT_KEY_LEADER_FILTHY_FIRSTGREETING_1','Welcome to the Rice Fields. Try not to touch anything.'),
('TXT_KEY_LEADER_FILTHY_GREETING_NEUTRAL_1','What brings you back to the Realm?'),
('TXT_KEY_LEADER_FILTHY_GREETING_HOSTILE_1','Your disgust only proves you are paying attention.'),
('TXT_KEY_LEADER_FILTHY_DOW_1','It is time for a higher form of diplomacy.'),
('TXT_KEY_LEADER_FILTHY_ATTACKED_1','You have entered the Realm willingly. Absolutely disgusting.'),
('TXT_KEY_LEADER_FILTHY_DEFEATED_1','It''s time to stop.'),
('TXT_KEY_LEADER_FILTHY_PEACE_1','Enough filth for one war. For now.'),
('TXT_KEY_LEADER_FILTHY_TRADE_ACCEPT_1','The route is open. Excellent.'),
('TXT_KEY_LEADER_FILTHY_TRADE_REJECT_1','Not filthy enough.'),
('TXT_KEY_LEADER_FILTHY_DENOUNCED_1','Negative attention is still attention.');
